examples.template:
VStack(alignment: .leading, spacing: 8) {
    MonarchPeriodSelector(
        selection: $period,
        presets: [{{presets.0}}, {{presets.1}}, {{presets.2}}, {{presets.3}}, {{presets.4}}, {{presets.5}}]
            .compactMap { MonarchPeriodPreset(rawValue: $0) },
        today: {{today|date}},
        maximumDays: {{maxDays}}
    )
    Text(verbatim: query)
        .monarchTextStyle(.caption)
}

examples.setupTemplate:
@State private var period = MonarchPeriod(MonarchPeriodPreset(rawValue: {{selected}}) ?? .last30Days)

/// The range the period resolves to, written as the web example's query line does.
private var query: String {
    var calendar = Calendar(identifier: .gregorian)
    calendar.timeZone = TimeZone(identifier: "UTC") ?? .gmt
    guard let range = period.resolved(today: {{today|date}}, calendar: calendar) else { return "" }
    let format = Date.ISO8601FormatStyle(timeZone: calendar.timeZone).year().month().day()
    return "Query: \(range.lowerBound.formatted(format)) – \(range.upperBound.formatted(format))"
}

examples.setup:
@State private var period = MonarchPeriod(MonarchPeriodPreset(rawValue: "30d") ?? .last30Days)

/// The range the period resolves to, written as the web example's query line does.
private var query: String {
    var calendar = Calendar(identifier: .gregorian)
    calendar.timeZone = TimeZone(identifier: "UTC") ?? .gmt
    guard let range = period.resolved(today: Date(timeIntervalSince1970: 1_794_009_600), calendar: calendar) else { return "" }
    let format = Date.ISO8601FormatStyle(timeZone: calendar.timeZone).year().month().day()
    return "Query: \(range.lowerBound.formatted(format)) – \(range.upperBound.formatted(format))"
}

@State private var period = MonarchPeriod(.thisQuarter)
@State private var query = ""
@Environment(\.calendar) private var calendar

examples.code:
VStack(alignment: .leading) {
    MonarchPeriodSelector(selection: $period)
    Text(query)
}
.onChange(of: period, initial: true) { _, period in
    if let days = period.resolved(today: .now, calendar: calendar) {
        query = "\(days.lowerBound.formatted(date: .numeric, time: .omitted)) to \(days.upperBound.formatted(date: .numeric, time: .omitted))"
    }
}
